select  business_date ,dataset_id ,pbor_node_name ,pbor_parent_node_name ,market_value_reporting_currency as mv_rc ,net_cash_flow_reporting_currency  as cf_rc,time_weighted_return_month_to_date_reporting_currency as twr_mtd_rc ,time_weighted_return_month_to_date_local_currency as twr_mtd_lc,time_weighted_return_quarter_to_date_reporting_currency as twr_qtd_rc ,time_weighted_return_quarter_to_date_local_currency as twr_qtd_lc ,time_weighted_return_fiscal_year_to_date_reporting_currency as twr_fytd_rc ,time_weighted_return_fiscal_year_to_date_local_currency as twr_fytd_lc,
time_weighted_return_1year_roll_reporting_currency as twr_1yr_roll_rc,time_weighted_return_1year_roll_local_currency as twr_1yr_roll_lc,time_weighted_return_3year_roll_reporting_currency as twr_3yr_roll_rc,time_weighted_return_3year_roll_local_currency as twr_3yr_roll_lc,time_weighted_return_5year_roll_reporting_currency as twr_5yr_roll_rc,time_weighted_return_5year_roll_local_currency as twr_5yr_roll_lc
